const D = { energy: .6, scale: 1, density: .55, speed: 1, wet: .55, glow: .6, hue: 190, x: .5, y: .72, style: 'limestone', act: 'drip', seed: 0, alpha: 1 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const ho = P.hue - 190;
const L3 = (a, b, f) => [a[0] + (b[0]-a[0])*f, a[1] + (b[1]-a[1])*f, a[2] + (b[2]-a[2])*f];
const sh = c => [hw(c[0] + ho), c[1], c[2]];
const NP = 4;                                    // stalactite curtains, 0 = deepest chamber

// ---------------- styles ----------------
const STY = {
  // cool grey-cream flowstone over a lit water table — the anchor: sacred, cold, enormous
  limestone: { void:[206,40,13], rockF:[200,16,40], rockN:[196,12,20], lit:[188,14,64], wat:[188,64,52],
               deep:[196,72,26], caus:[184,30,96], drip:[186,16,94], stip:0, poly:0, lamp:0, grain:22 },
  // a cenote — warm ochre rock, impossible turquoise water, daylight leaking from a far dome
  cenote:    { void:[28,54,8], rockF:[32,32,42], rockN:[26,38,20], lit:[38,26,66], wat:[172,72,58],
               deep:[186,80,28], caus:[168,40,98], drip:[44,20,96], stip:0, poly:0, lamp:0, grain:28 },
  // a caver's carbide lamp — one warm pool, the rest of the chamber only implied
  carbide:   { void:[222,52,10], rockF:[36,22,26], rockN:[30,26,14], lit:[40,44,58], wat:[200,44,22],
               deep:[210,60,11], caus:[42,30,86], drip:[44,26,92], stip:0, poly:0, lamp:1, grain:18 },
  // ABSTRACTED: a steel-engraved grotto plate — tone entirely from stipple and hatch, no fills
  stipple:   { void:[38,7,70], rockF:[38,9,50], rockN:[38,11,26], lit:[38,4,86], wat:[38,10,66],
               deep:[38,12,44], caus:[38,3,96], drip:[38,4,94], stip:1, poly:0, lamp:0, grain:10 },
  // ABSTRACTED: low-poly faceted crystal — the cave as a triangulated shell, hard facet shading
  lowpoly:   { void:[248,48,14], rockF:[262,34,44], rockN:[254,40,22], lit:[300,30,68], wat:[190,66,54],
               deep:[214,74,26], caus:[176,36,96], drip:[300,20,92], stip:0, poly:1, lamp:0, grain:6 }
};
const st = STY[P.style] || STY.limestone;

const en = Math.max(0, Math.min(1, P.energy));
const gl = Math.max(0, Math.min(1, P.glow));
const wy = height * P.y;                         // the water table
const lx = width * P.x;
const key = width + 'x' + height + '|' + P.style + '|' + P.seed + '|' + Math.round(P.hue) + '|' + P.scale.toFixed(2) + '|' + P.density.toFixed(2) + '|' + P.wet.toFixed(2) + '|' + P.y.toFixed(3) + '|' + P.x.toFixed(3);

if (!S.bg || S.key !== key) {
  const W = Math.max(2, Math.ceil(width)), H = Math.max(2, Math.ceil(height));
  const mk = (w, h) => { const g = createGraphics(Math.max(2, Math.ceil(w)), Math.max(2, Math.ceil(h))); g.colorMode(g.HSB, 360, 100, 100, 100); return g; };
  if (S.bg) { S.bg.remove(); S.pl.forEach(p => p.g.remove()); }
  S.bg = mk(W, H);

  // --- the void, and the far chamber glowing where the water runs away into the dark ---
  const g = S.bg; g.noStroke();
  const vC = sh(st.void), deepC = sh(st.deep), watC = sh(st.wat);
  for (let yy = 0; yy < H; yy++) {
    // the void is darkest at the ceiling and warms toward the water — light comes from BELOW here
    const f = Math.max(0, Math.min(1, yy / Math.max(1, wy)));
    const c = L3(vC, L3(vC, deepC, .55), Math.pow(f, 2.2));
    g.fill(c[0], c[1], c[2]); g.rect(0, yy, W, 1);
  }
  for (let i = 6; i >= 0; i--) {   // the far glow, sitting on the water line
    const f = i / 6;
    const c = L3(sh(st.caus), deepC, .35 + f * .6);
    g.fill(c[0], c[1] * (.5 + f * .5), c[2], (5 + 9 * gl) * (1 - f * .7));
    g.ellipse(lx, wy - u * .02, u * (.2 + f * 1.5), u * (.09 + f * .5));
  }

  S.tips = [];
  const rockFC = sh(st.rockF), rockNC = sh(st.rockN), litC = sh(st.lit);

  // --- one stalactite: a fluted taper. On the near planes it may reach the water as a column. ---
  const spike = (q, x, cy, len, w, id, col, lit2, near) => {
    const segs = 9;
    const px = f => x + Math.sin(f * 1.8 + fr(id + 1) * 6.3) * w * .5;
    const pw = f => w * Math.pow(1 - f, .78) * (1 + .12 * Math.sin(f * 11 + fr(id + 2) * 6.3));
    const py = f => cy + len * f;
    if (st.poly) {
      // low-poly: the spike is a strip of hard facets, each flat-shaded
      for (let i = 0; i < segs; i++) {
        const f0 = i / segs, f1 = (i + 1) / segs;
        for (const s2 of [-1, 1]) {
          const shade = .35 + .5 * Math.abs(Math.sin(i * 2.1 + fr(id + i) * 6.3)) + (s2 > 0 ? .18 : 0);
          const c = L3(col, lit2, Math.max(0, Math.min(1, shade * (.4 + f0 * .9))));
          q.fill(c[0], c[1], c[2], 100); q.noStroke();
          q.triangle(px(f0), py(f0), px(f0) + s2 * pw(f0) / 2, py(f0) + len * .02, px(f1) + s2 * pw(f1) / 2, py(f1));
          q.triangle(px(f0), py(f0), px(f1) + s2 * pw(f1) / 2, py(f1), px(f1), py(f1));
        }
      }
      return;
    }
    if (st.stip) {
      // engraving: no fill anywhere — the form is stipple density alone
      const n = Math.floor(120 * (.3 + near) * (.4 + len / u));
      q.noStroke();
      for (let i = 0; i < n; i++) {
        const f = Math.pow(fr(id * 7 + i), .7);
        const o = (fr(id * 11 + i * 3) - .5) * pw(f);
        const lam = .5 + .5 * Math.cos((o / Math.max(1, pw(f)) - (P.x - .5)) * 3.2);
        // stipple gets denser where the form turns away from the water light
        if (fr(id * 13 + i * 5) < lam * .55 + (1 - f) * .2) continue;
        q.fill(col[0], col[1], Math.max(2, col[2] * .35), 60);
        q.rect(px(f) + o, py(f), 1.5, 1.5);
      }
      q.noStroke(); q.noFill();
      q.strokeWeight(Math.max(.4, u * .0009));
      q.stroke(col[0], col[1], Math.max(2, col[2] * .4), 60);
      for (const s2 of [-1, 1]) { q.beginShape(); for (let i = 0; i <= segs; i++) { const f = i / segs; q.vertex(px(f) + s2 * pw(f) / 2, py(f)); } q.endShape(); }
      q.noStroke();
      return;
    }
    q.noStroke(); q.fill(col[0], col[1], col[2], 100);
    q.beginShape();
    for (let i = 0; i <= segs; i++) { const f = i / segs; q.vertex(px(f) - pw(f) / 2, py(f)); }
    for (let i = segs; i >= 0; i--) { const f = i / segs; q.vertex(px(f) + pw(f) / 2, py(f)); }
    q.endShape(q.CLOSE);
    // flutes: the calcite ribs. And the underside catches the water light — form from below.
    q.noFill(); q.strokeWeight(Math.max(.4, w * .07));
    for (let s2 = 0; s2 < 6; s2++) {
      const o = (s2 / 5 - .5) * .84;
      const lam = .5 + .5 * Math.cos((o - (P.x - .5) * 1.2) * 2.6);
      q.stroke(col[0], col[1] * (.8 + .5 * (1 - lam)), Math.max(2, col[2] * (.6 + .5 * lam) + (fr(id * 5 + s2) - .5) * 7), 46);
      q.beginShape();
      for (let i = 0; i <= segs; i++) { const f = i / segs; q.vertex(px(f) + o * pw(f) / 2, py(f)); }
      q.endShape();
    }
    q.noStroke();
    // the wet tip — the brightest thing on the spike, because the water is lighting it
    q.fill(lit2[0], lit2[1] * .6, lit2[2], (30 + 40 * P.wet) * (.4 + near * .8));
    q.ellipse(px(.97), py(.97), Math.max(1.5, pw(.9) * 1.5), Math.max(1.5, pw(.9) * 2.2));
  };

  // --- the curtains, deepest chamber first ---
  S.pl = [];
  for (let L = 0; L < NP; L++) {
    const near = L / (NP - 1);
    const ceilY = height * (.30 - .44 * near);
    const bh = Math.max(4, Math.ceil(wy - ceilY + u * .1));
    const q = mk(W, bh);
    const haze = (1 - near) * .62;
    const col = L3(L3(rockFC, rockNC, near), sh(st.deep), haze * .8);
    const lit2 = L3(litC, sh(st.deep), haze * .6);

    // the ceiling itself: a rolling solution dome, not a straight edge
    if (!st.stip) {
      q.noStroke(); q.fill(col[0], col[1], Math.max(2, col[2] * .7), 100);
      q.beginShape(); q.vertex(-20, -20); q.vertex(W + 20, -20);
      for (let xx = W + 20; xx >= -20; xx -= 16) {
        const n = Math.sin(xx * .0039 + fr(L * 7 + 1) * 6.3) * .5 + Math.sin(xx * .0111 + fr(L * 7 + 2) * 6.3) * .28 + Math.sin(xx * .0017) * .5;
        q.vertex(xx, u * (.03 + .05 * near) + n * u * (.02 + .03 * near));
      }
      q.endShape(q.CLOSE);
    }

    const n = Math.max(2, Math.round((3 + fr(L * 13 + 3) * 3 + P.density * 7) * (near < .4 ? 1.5 : 1)));
    for (let i = 0; i < n; i++) {
      const id = L * 149 + i * 23 + 7;
      const x = W * ((i + .5 + (fr(id + 4) - .5) * .85) / n);
      const maxLen = (wy - ceilY) * (.30 + fr(id + 5) * .62) * (.5 + P.scale * .6);
      const len = Math.min(maxLen, (wy - ceilY) * .98);
      const w = Math.max(1.5, len * (.05 + fr(id + 6) * .07));
      const cy = u * (.03 + .05 * near) + Math.sin(x * .0039 + fr(L * 7 + 1) * 6.3) * u * (.02 + .03 * near);
      spike(q, x, cy, len, w, id, col, lit2, near);
      // a drip hangs off any tip that clears the water — screen coords, for the live pass
      if (cy + len < wy - ceilY - u * .04 && S.tips.length < 26)
        S.tips.push({ x: x, y: ceilY + cy + len, near: near, w: w });
    }
    // per-plane haze: the chambers must separate in value or the depth dies
    if (!st.stip) { q.noStroke(); q.fill(sh(st.deep)[0], st.deep[1], st.deep[2], (1 - near) * 26); q.rect(0, 0, W, bh); }
    S.pl.push({ g: q, y: ceilY, near: near });
  }
  S.key = key;
}

// ---------------- act ----------------
const sec = ((Math.floor(K.section) % 8) + 8) % 8;
const ACT = { drip: { r: 1, g: .9 + sec * .012 }, flood: { r: 1.6 + sec * .1, g: 1 }, silent: { r: .35, g: .7 + sec * .04 } };
const act = ACT[P.act] || ACT.drip;

noStroke();
image(S.bg, 0, 0);

// ---------------- the water table: a lit, translucent volume, NOT a mirror ----------------
const watC2 = sh(st.wat), deepC2 = sh(st.deep), causC = sh(st.caus);
fill(watC2[0], watC2[1], watC2[2] * .6); rect(0, wy, width, height - wy);
blendMode(ADD);
for (let i = 0; i < 20; i++) {
  // light rising through the water column — three incommensurate terms, never a pulse
  const f = fr(i * 3 + 11);
  const sm = .5 + .5 * (Math.sin(K.t * (.61 + i * .014) + i) * .55 + Math.sin(K.t * 1.43 + i * 2.1) * .3 + Math.sin(K.t * 2.29 + i) * .15);
  const gain = (.35 + .65 * en) * gl * (.4 + .6 * sm) + A.rms * .3;
  fill(watC2[0], watC2[1] * .7, watC2[2], (4 + 12 * gain));
  ellipse(lx + (f - .5) * width * .9, wy + fr(i * 3 + 12) * (height - wy), u * (.1 + .3 * sm), u * (.03 + .1 * f));
}
blendMode(BLEND);
// submerged rock, seen THROUGH the water — depth in the volume, not a reflection
for (let i = 0; i < 7; i++) {
  const f = i / 7;
  fill(deepC2[0], deepC2[1], deepC2[2], 22 * (1 - f));
  ellipse(lx + (fr(i * 5 + 21) - .5) * width * .8, wy + u * .04 + f * (height - wy) * .9, u * (.3 + f * .7), u * (.05 + f * .12));
}

// slow camera drift, two incommensurate rates
const ddx = (Math.sin(K.t * .014) * .7 + Math.sin(K.t * .0331 + 1.2) * .3) * u * .005 * P.speed;

// ---------------- curtains, deepest first ----------------
for (let L = 0; L < NP; L++) {
  const p = S.pl[L];
  image(p.g, ddx * (.2 + p.near), p.y + Math.sin(K.t * (.021 + L * .009) + L * 2.3) * u * .0015);
}

// ---------------- CAUSTICS: the water throws a moving net of light UP onto the stone ----------------
if (!st.stip) {
  blendMode(ADD);
  const nc = Math.floor(26 + P.density * 44);
  for (let i = 0; i < nc; i++) {
    const a = fr(i * 3 + 31), b = fr(i * 3 + 32);
    // a wandering interference lattice: incommensurate in both axes
    const cx2 = width * (a * 1.25 - .12) + Math.sin(K.t * (.37 + a * .5) + i) * u * .05 + Math.sin(K.t * 1.13 + i * 2.1) * u * .02;
    const hh = Math.pow(b, 1.7);                        // hug the water, thin out toward the ceiling
    const cy2 = wy - hh * (wy * .95);
    const fall = Math.pow(1 - hh, 1.4);                 // the net dies as it climbs
    const sm = .5 + .5 * (Math.sin(K.t * (.61 + i * .021) + i * 1.7) * .6 + Math.sin(K.t * 1.43 + i) * .28 + Math.sin(K.t * 2.29 + i * .5) * .12);
    const gain = (.3 + .7 * en) * gl * (.25 + .75 * sm) * fall + A.treble * .12 * fall;
    push();
    translate(cx2, cy2);
    rotate(Math.sin(K.t * .19 + i * 2.3) * .9 + i);
    fill(causC[0], causC[1] * (.5 + .5 * fall), causC[2], (2 + 16 * gain));
    ellipse(0, 0, u * (.02 + .13 * sm) * (.4 + fall), u * .006 * (.3 + fall));
    pop();
  }
  blendMode(BLEND);
}

// ---------------- drips: form, fall, strike, ring. A continuous clock, never a flash. ----------------
const dripC = sh(st.drip);
if (S.tips && S.tips.length) {
  for (let i = 0; i < S.tips.length; i++) {
    const tp = S.tips[i];
    const rate = (.12 + fr(i * 5 + 41) * .22) * act.r * P.speed;
    const life = ((K.t * rate + fr(i * 5 + 42)) % 1);
    const dx = tp.x + ddx * (.2 + tp.near);
    if (life < .78) {
      const ff = Math.max(0, (life - .42) / .36);
      const dy = tp.y + Math.pow(ff, 2) * (wy - tp.y);
      const swell2 = life < .42 ? (life / .42) : 1;
      fill(dripC[0], dripC[1], dripC[2], (30 + 40 * en) * (.3 + .7 * tp.near));
      ellipse(dx, dy, Math.max(1.2, tp.w * .5 * swell2), Math.max(1.6, tp.w * .8 * swell2 * (1 + ff * .8)));
    } else {
      const age = (life - .78) / .22;
      noFill(); strokeWeight(Math.max(.5, u * .0014 * (1 - age)));
      stroke(dripC[0], dripC[1] * .5, dripC[2], 44 * (1 - age) * (.3 + .7 * en));
      const rr = age * u * .07 * (.4 + tp.near);
      ellipse(dx, wy, rr * 2, rr * .45);
      noStroke();
    }
  }
}

// ---------------- carbide lamp: one warm pool, if that's the style ----------------
if (st.lamp) {
  blendMode(ADD);
  const fl = .84 + .09 * Math.sin(K.t * 1.9) + .07 * Math.sin(K.t * .67 + 1.1);   // a lamp flutter, far below any strobe
  for (let i = 4; i >= 0; i--) {
    fill(sh(st.lit)[0], st.lit[1] * (.8 - i * .12), st.lit[2], (4 + 8 * en) * fl * (1 - i * .15));
    ellipse(lx + Math.sin(K.t * .07) * u * .03, wy - u * .18, u * (.08 + i * .3), u * (.08 + i * .28));
  }
  blendMode(BLEND);
}

if (st.grain > 6) {
  const ng = Math.floor(st.grain * 6);
  for (let i = 0; i < ng; i++) {
    const gx = ((fr(i * 3 + 701) * width) + Math.sin(K.t * .012 + i) * u * .003 + width) % width;
    const gy = fr(i * 3 + 702) * height;
    fill(hw(st.rockN[0] + ho), st.rockN[1] * .5, fr(i * 3 + 703) > .5 ? 90 : 4, 3 + fr(i) * 6);
    rect(gx, gy, u * .0016, u * .0016);
  }
}
for (let i = 0; i < 5; i++) {
  noFill(); strokeWeight(u * .055);
  stroke(hw(st.void[0] + ho), st.void[1], st.stip ? 86 : 5, 24 * (1 - i * .17));
  rect(-u * .03 + i * u * .03, -u * .03 + i * u * .03, width + u * .06 - i * u * .06, height + u * .06 - i * u * .06);
}
noStroke();

if (P.alpha < 1) { fill(hw(st.void[0] + ho), st.void[1] * .5, 4, (1 - P.alpha) * 100); rect(0, 0, width, height); }
blendMode(BLEND);
drawingContext.shadowBlur = 0;
